import java.io.*;
import java.net.*;
import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import org.json.*;

public class ReportServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportId = req.getParameter("id");
        String format = req.getParameter("format");
        String tenantId = req.getHeader("X-Tenant-ID");

        if (reportId == null || tenantId == null) {
            resp.sendError(400, "Missing parameters");
            return;
        }

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            // Build query - note: tenantId comes from header, reportId from param
            String query = "SELECT r.title, r.content, r.created_at, u.email " +
                          "FROM reports r JOIN users u ON r.author_id = u.id " +
                          "WHERE r.tenant_id = '" + tenantId + "' " +
                          "AND r.id = '" + reportId + "'";

            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(query);

            JSONObject result = new JSONObject();
            if (rs.next()) {
                result.put("title", rs.getString("title"));
                result.put("content", rs.getString("content"));
                result.put("created_at", rs.getString("created_at"));
                result.put("author_email", rs.getString("email"));
            } else {
                resp.sendError(404, "Report not found");
                return;
            }

            // Audit logging - writes to separate audit table
            String auditSql = "INSERT INTO audit_log (action, tenant_id, resource_id, ts) " +
                             "VALUES ('VIEW_REPORT', ?, ?, NOW())";
            PreparedStatement auditStmt = conn.prepareStatement(auditSql);
            auditStmt.setString(1, tenantId);
            auditStmt.setString(2, reportId);
            auditStmt.executeUpdate();

            // Format response
            if ("xml".equals(format)) {
                resp.setContentType("application/xml");
                resp.getWriter().write(toXml(result));
            } else {
                resp.setContentType("application/json");
                resp.getWriter().write(result.toString());
            }
        } catch (SQLException e) {
            resp.sendError(500, "Database error");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String tenantId = req.getHeader("X-Tenant-ID");
        BufferedReader reader = req.getReader();
        StringBuilder body = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            body.append(line);
        }

        try {
            JSONObject payload = new JSONObject(body.toString());
            String title = payload.getString("title");
            String content = payload.getString("content");

            try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
                // This one uses prepared statement correctly
                String sql = "INSERT INTO reports (tenant_id, title, content, created_at) VALUES (?, ?, ?, NOW())";
                PreparedStatement ps = conn.prepareStatement(sql);
                ps.setString(1, tenantId);
                ps.setString(2, title);
                ps.setString(3, content);
                ps.executeUpdate();

                resp.setStatus(201);
                resp.getWriter().write("{\"status\":\"created\"}");
            }
        } catch (Exception e) {
            resp.sendError(500, "Error creating report");
        }
    }

    private String toXml(JSONObject json) {
        StringBuilder sb = new StringBuilder("<?xml version=\"1.0\"?>\n<report>\n");
        for (String key : json.keySet()) {
            sb.append("  <").append(key).append(">");
            sb.append(json.getString(key));
            sb.append("</").append(key).append(">\n");
        }
        sb.append("</report>");
        return sb.toString();
    }
}
